/** A menu symbol tinted with [color]; [filled] draws the filled variant (the current section). */
@Composable internal fun MenuSymbol(name: String, filled: Boolean, color: Color, modifier: Modifier = Modifier) {
    val data = (if (filled) filledSymbols else outlineSymbols).getValue(name)
    val vector = remember(data) {
        ImageVector.Builder(defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 960f, viewportHeight = 960f)
            .addGroup(translationY = 960f)
            .addPath(addPathNodes(data), fill = SolidColor(Color.White))
            .clearGroup().build()
    }
    Image(rememberVectorPainter(vector), null, modifier, colorFilter = ColorFilter.tint(color))
}
